def ask(prompt):
    body=json.dumps({'model':MODEL,'messages':[{'role':'user','content':prompt}], 'stream':False,'think':THINK,'options':{'temperature':0,'seed':42,'num_predict':256}}).encode()
    req=urllib.request.Request('http://127.0.0.1:11434/api/chat',data=body,headers={'Content-Type':'application/json'})
    with urllib.request.urlopen(req,timeout=420) as r: return json.loads(r.read().decode())

def pick(s):
    s=s.strip().upper()
    lines=[x.strip() for x in s.splitlines() if x.strip()]
    if lines and re.fullmatch(r'[ABCD][\).]?',lines[-1]): return lines[-1][0]
    m=re.search(r'(?:ОТВЕТ|ANSWER)\s*[:\-]?\s*([ABCD])',s)
    if m:return m.group(1)
    m=re.search(r'\b([ABCD])\b',s)
    return m.group(1) if m else '?'

rows=[]; t0=time.time()
for iid,cat,q,opts,ans in Q:
    prompt='Ответь на тест. Выбери ровно один вариант A, B, C или D. В последней строке напиши только букву ответа.\n\n'+q+'\n'+'\n'.join(opts)
    ts=time.time()
    try:
        z=ask(prompt); raw=z.get('message',{}).get('content',''); thinking=z.get('message',{}).get('thinking',''); pred=pick(raw); err=None
    except Exception as e:
        raw='';thinking='';pred='?';err=repr(e)
    rows.append({'id':iid,'cat':cat,'q':q,'options':opts,'answer':ans,'pred':pred,'correct':pred==ans,'raw':raw,'thinking':thinking,'error':err,'sec':time.time()-ts})
    print(MODEL,iid,pred,ans,pred==ans,flush=True)
cats={}
for c in sorted({r['cat'] for r in rows}):
    z=[r for r in rows if r['cat']==c]; cats[c]={'n':len(z),'correct':sum(r['correct'] for r in z),'accuracy':sum(r['correct'] for r in z)/len(z)}
res={'model':MODEL,'think':THINK,'n':len(rows),'correct':sum(r['correct'] for r in rows),'accuracy':sum(r['correct'] for r in rows)/len(rows),'categories':cats,'elapsed_sec':time.time()-t0,'rows':rows}
OUT.write_text(json.dumps(res,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({k:v for k,v in res.items() if k!='rows'},ensure_ascii=False,indent=2))
